#!/bin/bash

# Sets up external dependencies (Valkey, CloudNativePG, Garage) for local chart development.
#
# Usage:
#   scripts/dev_dependencies.sh setup    - Deploy all external dependencies
#   scripts/dev_dependencies.sh teardown - Remove all deployed external dependencies
#   scripts/dev_dependencies.sh status   - Show status of external dependencies
#
# Environment variables:
#   NAMESPACE           - Kubernetes namespace (default: gitlab)
#   VALKEY_PASSWORD     - Valkey password (default: auto-generated and saved to .values/)
#   GARAGE_APP_VERSION  - Garage version (default: 2.2.0)
#   CNPG_POSTGRESQL_TAG - PostgreSQL image tag for CloudNativePG (default: 17)

set -eo pipefail
[[ "${TRACE}" ]] && set -x

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${SCRIPT_DIR}/.."
VALUES_DIR="${PROJECT_ROOT}/.values"

NAMESPACE="${NAMESPACE:-gitlab}"
VALKEY_RELEASE="dev-valkey"
CNPG_RELEASE="dev-cnpg"
CNPG_CLUSTER="dev-cluster"
GARAGE_APP_VERSION="${GARAGE_APP_VERSION:-2.2.0}"
CNPG_POSTGRESQL_TAG="${CNPG_POSTGRESQL_TAG:-17}"

STATE_FILE="${VALUES_DIR}/dev-state.env"
GENERATED_VALUES="${VALUES_DIR}/dev-external.values.yaml"

function check_prerequisites() {
  for tool in kubectl helm; do
    if ! command -v "${tool}" > /dev/null 2>&1; then
      echo "ERROR: ${tool} is required but not installed."
      echo "See doc/development/environment_setup.md for guidance."
      exit 1
    fi
  done
}

function ensure_namespace() {
  kubectl get namespace "${NAMESPACE}" > /dev/null 2>&1 \
    || kubectl create namespace "${NAMESPACE}"
  echo "    Namespace: ${NAMESPACE}"
}

function ensure_valkey_password() {
  mkdir -p "${VALUES_DIR}"
  # shellcheck disable=SC1090
  [ -f "${STATE_FILE}" ] && source "${STATE_FILE}"
  if [ -z "${VALKEY_PASSWORD}" ]; then
    { set +o pipefail; VALKEY_PASSWORD="$(LC_ALL=C tr -dc A-Za-z0-9 </dev/urandom | head -c 20)"; set -o pipefail; }
    echo "# Generated by scripts/dev_dependencies.sh - do not commit this file." > "${STATE_FILE}"
    echo "VALKEY_PASSWORD=\"${VALKEY_PASSWORD}\"" >> "${STATE_FILE}"
    echo "    Generated Valkey password and saved to ${STATE_FILE}"
  fi
}

# Valkey

function setup_valkey() {
  echo "==> Setting up Valkey..."
  ensure_valkey_password

  helm repo add valkey https://valkey.io/valkey-helm/ --force-update > /dev/null

  helm upgrade --install "${VALKEY_RELEASE}" valkey/valkey \
    --namespace "${NAMESPACE}" \
    --set dataStorage.enabled=true \
    --set dataStorage.size=2Gi \
    --set metrics.enabled=true \
    --set auth.enabled=true \
    --set "auth.aclUsers.default.permissions=~* &* +@all" \
    --set "auth.aclUsers.default.password=${VALKEY_PASSWORD}" \
    --wait \
    --hide-notes

  echo "    Valkey ready."
}

function teardown_valkey() {
  echo "    Removing Valkey..."
  helm uninstall "${VALKEY_RELEASE}" --namespace "${NAMESPACE}" --ignore-not-found 2>/dev/null || true
}

# CloudNativePG

function setup_cnpg() {
  echo "==> Setting up CloudNativePG operator..."

  helm repo add cnpg https://cloudnative-pg.github.io/charts --force-update > /dev/null

  helm upgrade --install "${CNPG_RELEASE}" cnpg/cloudnative-pg \
    --namespace "${NAMESPACE}" \
    --set config.clusterWide=false \
    --wait \
    --hide-notes

  echo "==> Creating PostgreSQL cluster (${CNPG_CLUSTER})..."

  # Retry the apply because the CNPG webhook may not be ready immediately after operator install.
  # See https://github.com/cloudnative-pg/charts/issues/674
  local applied=0
  for i in $(seq 1 10); do
    if cat <<EOF | kubectl apply --namespace "${NAMESPACE}" -f -
apiVersion: postgresql.cnpg.io/v1
kind: Cluster
metadata:
  name: "${CNPG_CLUSTER}"
  namespace: "${NAMESPACE}"
spec:
  instances: 1
  imageName: "ghcr.io/cloudnative-pg/postgresql:${CNPG_POSTGRESQL_TAG}"
  storage:
    size: 5Gi
  postgresql:
    parameters:
      max_connections: "200"
      shared_buffers: "256MB"
  bootstrap:
    initdb:
      database: gitlabhq_production
      owner: gitlab
      postInitSQL:
        - CREATE EXTENSION IF NOT EXISTS pg_trgm;
        - CREATE EXTENSION IF NOT EXISTS btree_gist;
        - CREATE EXTENSION IF NOT EXISTS plpgsql;
        - CREATE EXTENSION IF NOT EXISTS amcheck;
        - CREATE EXTENSION IF NOT EXISTS pg_stat_statements;
EOF
    then
      applied=1
      break
    fi
    echo "    Webhook not ready yet, retrying (${i}/10)..."
    sleep 10
  done

  if [ "${applied}" -eq 0 ]; then
    echo "ERROR: Failed to apply PostgreSQL cluster after 10 attempts."
    exit 1
  fi

  # Retry waiting because the webhook may not be ready immediately after install.
  echo "    Waiting for PostgreSQL cluster to be ready (this may take a few minutes)..."
  local ready=0
  for i in $(seq 1 10); do
    if kubectl wait --timeout 30s --for=condition=Ready \
        --namespace "${NAMESPACE}" "clusters/${CNPG_CLUSTER}" 2>/dev/null; then
      ready=1
      break
    fi
    echo "    Not ready yet, retrying (${i}/10)..."
    sleep 10
  done

  if [ "${ready}" -eq 0 ]; then
    echo "ERROR: PostgreSQL cluster did not become ready in time."
    kubectl get clusters --namespace "${NAMESPACE}"
    exit 1
  fi

  echo "    CloudNativePG cluster ready."
}

function teardown_cnpg() {
  echo "    Removing CloudNativePG cluster..."
  kubectl delete --namespace "${NAMESPACE}" --wait --ignore-not-found=true \
    "cluster/${CNPG_CLUSTER}" 2>/dev/null || true

  echo "    Removing CloudNativePG operator..."
  helm uninstall "${CNPG_RELEASE}" --namespace "${NAMESPACE}" --ignore-not-found 2>/dev/null || true
}

# Garage (object storage)

function setup_garage() {
  echo "==> Setting up Garage (object storage)..."

  if ! helm plugin list 2>/dev/null | grep -q "helm-git"; then
    echo "    Installing helm-git plugin..."
    helm plugin install https://github.com/aslafy-z/helm-git
  fi

  helm repo add garage \
    "git+https://git.deuxfleurs.fr/Deuxfleurs/garage.git@script/helm?ref=v${GARAGE_APP_VERSION}" \
    --force-update > /dev/null
  helm repo update > /dev/null

  helm upgrade --install garage garage/garage \
    --namespace "${NAMESPACE}" \
    --set garage.replicationFactor=1 \
    --set deployment.replicaCount=1 \
    --set persistence.data.size=5Gi \
    --set persistence.meta.size=250Mi \
    --set resources.requests.memory="256Mi" \
    --set resources.requests.cpu="100m" \
    --set resources.limits.memory="512Mi" \
    --set resources.limits.cpu="500m" \
    --wait --timeout=300s

  local GARAGE_POD
  GARAGE_POD=$(kubectl get pod \
    --namespace "${NAMESPACE}" \
    -l app.kubernetes.io/name=garage \
    -o jsonpath='{.items[0].metadata.name}')

  echo "    Using Garage pod: ${GARAGE_POD}"

  local NODE_ID
  NODE_ID=$(kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
    /garage status 2>/dev/null | grep -oE '[0-9a-f]{16}' | head -1)

  if [ -z "${NODE_ID}" ]; then
    echo "ERROR: Could not detect Garage node ID."
    kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- /garage status
    exit 1
  fi

  echo "    Assigning Garage layout (node: ${NODE_ID})..."
  kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
    /garage layout assign -z dev -c 5G "${NODE_ID}" || true
  kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
    /garage layout apply --version 1 2>/dev/null \
    || kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
       /garage layout apply --version 2 2>/dev/null || true

  local BUCKETS=(
    "git-lfs"
    "gitlab-artifacts"
    "gitlab-backups"
    "gitlab-ci-secure-files"
    "gitlab-dependency-proxy"
    "gitlab-mr-diffs"
    "gitlab-packages"
    "gitlab-pages"
    "gitlab-terraform-state"
    "gitlab-uploads"
    "registry"
    "runner-cache"
    "tmp"
  )

  echo "    Creating buckets..."
  for bucket in "${BUCKETS[@]}"; do
    kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
      /garage bucket create "${bucket}" 2>/dev/null \
      && echo "      Created: ${bucket}" \
      || echo "      Already exists: ${bucket}"
  done

  # Skip key/secret creation if credentials already exist.
  if kubectl get secret gitlab-object-storage --namespace "${NAMESPACE}" > /dev/null 2>&1; then
    echo "    Garage Kubernetes Secrets already exist, skipping key creation."
    echo "    Garage ready."
    return
  fi

  echo "    Creating Garage API key..."
  local KEY_OUTPUT
  KEY_OUTPUT=$(kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
    /garage key create gitlab-app-key)

  local GARAGE_ACCESS_KEY GARAGE_SECRET_KEY
  GARAGE_ACCESS_KEY=$(echo "${KEY_OUTPUT}" | grep 'Key ID:' | awk '{print $3}')
  GARAGE_SECRET_KEY=$(echo "${KEY_OUTPUT}" | grep 'Secret key:' | awk '{print $3}')

  if [ -z "${GARAGE_ACCESS_KEY}" ] || [ -z "${GARAGE_SECRET_KEY}" ]; then
    echo "ERROR: Failed to extract Garage API credentials from output:"
    echo "${KEY_OUTPUT}"
    exit 1
  fi

  echo "    Granting bucket permissions..."
  for bucket in "${BUCKETS[@]}"; do
    kubectl exec --namespace "${NAMESPACE}" "${GARAGE_POD}" -- \
      /garage bucket allow --read --write --key "${GARAGE_ACCESS_KEY}" "${bucket}"
  done

  echo "    Creating Kubernetes Secrets for Garage access..."

  kubectl create secret generic gitlab-object-storage \
    --namespace "${NAMESPACE}" \
    --from-literal=config="$(cat <<EOF
provider: AWS
region: garage
aws_access_key_id: ${GARAGE_ACCESS_KEY}
aws_secret_access_key: ${GARAGE_SECRET_KEY}
endpoint: "http://garage.${NAMESPACE}.svc.cluster.local:3900"
path_style: true
EOF
)" --dry-run=client -o yaml | kubectl apply -f -

  kubectl create secret generic gitlab-object-storage-s3cmd \
    --namespace "${NAMESPACE}" \
    --from-literal=config="$(cat <<EOF
[default]
access_key = ${GARAGE_ACCESS_KEY}
secret_key = ${GARAGE_SECRET_KEY}
host_base = garage.${NAMESPACE}.svc.cluster.local:3900
host_bucket = garage.${NAMESPACE}.svc.cluster.local:3900
use_https = False
EOF
)" --dry-run=client -o yaml | kubectl apply -f -

  kubectl create secret generic gitlab-registry-storage \
    --namespace "${NAMESPACE}" \
    --from-literal=config="$(cat <<EOF
s3:
  accesskey: ${GARAGE_ACCESS_KEY}
  secretkey: ${GARAGE_SECRET_KEY}
  bucket: registry
  region: garage
  regionendpoint: http://garage.${NAMESPACE}.svc.cluster.local:3900
  secure: false
  v4auth: true
  pathstyle: true
EOF
)" --dry-run=client -o yaml | kubectl apply -f -

  echo "    Garage ready."
}

function teardown_garage() {
  echo "    Removing Garage..."
  helm uninstall garage --namespace "${NAMESPACE}" --ignore-not-found 2>/dev/null || true

  kubectl delete pvc \
    --namespace "${NAMESPACE}" \
    -l app.kubernetes.io/name=garage \
    --ignore-not-found 2>/dev/null || true

  kubectl delete secret \
    gitlab-object-storage \
    gitlab-object-storage-s3cmd \
    gitlab-registry-storage \
    --namespace "${NAMESPACE}" --ignore-not-found 2>/dev/null || true
}

# Values file

function generate_values_file() {
  mkdir -p "${VALUES_DIR}"

  cat > "${GENERATED_VALUES}" <<EOF
# Generated by scripts/dev_dependencies.sh - do not commit this file.
# Use this values file when deploying the GitLab chart locally.
# See doc/development/external-dependencies.md for usage.

redis:
  install: false

global:
  redis:
    host: "${VALKEY_RELEASE}"
    auth:
      secret: "${VALKEY_RELEASE}-auth"
      key: default-password
  psql:
    host: "${CNPG_CLUSTER}-rw"
    password:
      secret: "${CNPG_CLUSTER}-app"
      key: password
  minio:
    enabled: false
  appConfig:
    object_store:
      enabled: true
      proxy_download: true
      connection:
        secret: gitlab-object-storage
        key: config
    artifacts:
      bucket: gitlab-artifacts
    lfs:
      bucket: git-lfs
    uploads:
      bucket: gitlab-uploads
    packages:
      bucket: gitlab-packages
    externalDiffs:
      enabled: true
      bucket: gitlab-mr-diffs
    terraformState:
      enabled: true
      bucket: gitlab-terraform-state
    ciSecureFiles:
      enabled: true
      bucket: gitlab-ci-secure-files
    dependencyProxy:
      enabled: true
      bucket: gitlab-dependency-proxy

postgresql:
  install: false

gitlab:
  toolbox:
    backups:
      objectStorage:
        config:
          secret: gitlab-object-storage-s3cmd
          key: config

registry:
  storage:
    secret: gitlab-registry-storage
    key: config
    redirect:
      disable: true
EOF

  echo "    Generated values file: ${GENERATED_VALUES}"
}

# Commands

function cmd_setup() {
  echo "Setting up external dependencies in namespace '${NAMESPACE}'..."
  echo ""
  check_prerequisites
  ensure_namespace
  setup_valkey
  setup_cnpg
  setup_garage
  generate_values_file

  echo ""
  echo "==> All external dependencies are ready."
  echo ""
  echo "Deploy the GitLab chart with:"
  echo ""
  echo "  helm dependency update"
  echo "  helm upgrade --install gitlab . \\"
  echo "    --namespace ${NAMESPACE} \\"
  echo "    --timeout 600s \\"
  echo "    -f .values/dev-external.values.yaml \\"
  echo "    --set global.hosts.domain=<YOUR_DOMAIN> \\"
  echo "    --set global.hosts.externalIP=<YOUR_IP> \\"
  echo "    --set certmanager-issuer.email=<YOUR_EMAIL>"
  echo ""
  echo "See doc/development/external-dependencies.md for more details."
}

function cmd_teardown() {
  echo "Removing external dependencies from namespace '${NAMESPACE}'..."
  echo ""
  teardown_valkey
  teardown_cnpg
  teardown_garage
  echo ""
  echo "==> External dependencies removed."
  echo ""
  echo "The namespace '${NAMESPACE}' and GitLab chart release are not affected."
  echo "Run 'helm uninstall gitlab --namespace ${NAMESPACE}' to remove GitLab as well."
}

function cmd_status() {
  echo "External dependency status in namespace '${NAMESPACE}':"
  echo ""

  echo "--- Valkey (${VALKEY_RELEASE}) ---"
  kubectl get deployment \
    --namespace "${NAMESPACE}" \
    -l "app.kubernetes.io/instance=${VALKEY_RELEASE}" 2>/dev/null \
    || echo "  Not found"

  echo ""
  echo "--- CloudNativePG operator (${CNPG_RELEASE}) ---"
  kubectl get deployment \
    --namespace "${NAMESPACE}" \
    -l "app.kubernetes.io/instance=${CNPG_RELEASE}" 2>/dev/null \
    || echo "  Not found"

  echo ""
  echo "--- PostgreSQL cluster (${CNPG_CLUSTER}) ---"
  kubectl get cluster \
    --namespace "${NAMESPACE}" \
    "${CNPG_CLUSTER}" 2>/dev/null \
    || echo "  Not found"

  echo ""
  echo "--- Garage ---"
  kubectl get statefulset \
    --namespace "${NAMESPACE}" \
    -l app.kubernetes.io/name=garage 2>/dev/null \
    || echo "  Not found"

  echo ""
  echo "--- Object storage secrets ---"
  for secret in gitlab-object-storage gitlab-object-storage-s3cmd gitlab-registry-storage; do
    kubectl get secret --namespace "${NAMESPACE}" "${secret}" \
      -o jsonpath="  {.metadata.name}: present{'\n'}" 2>/dev/null \
      || echo "  ${secret}: not found"
  done
}

function usage() {
  cat <<EOF
Usage: $0 {setup|teardown|status}

  setup    Deploy Valkey, CloudNativePG, and Garage as external GitLab dependencies.
  teardown Remove the deployed external dependencies (does not remove the GitLab release).
  status   Show the current status of the external dependencies.

Environment variables:
  NAMESPACE           Kubernetes namespace to use (default: gitlab)
  VALKEY_PASSWORD     Password for Valkey auth (default: auto-generated)
  GARAGE_APP_VERSION  Garage version to install (default: 2.2.0)
  CNPG_POSTGRESQL_TAG PostgreSQL image tag for CloudNativePG (default: 17)

See doc/development/external-dependencies.md for full documentation.
EOF
  exit 1
}

case "${1:-}" in
  setup)    cmd_setup ;;
  teardown) cmd_teardown ;;
  status)   cmd_status ;;
  *)        usage ;;
esac
